// Genesis-free C++ port of the F1TENTH observation pipeline.
//
// Reproduces ros2_deploy/f1tenth_rl_agent/f1tenth_rl_agent/obs_core.py (which is in
// turn numerically identical to the training f1tenth_env/observations.py) for the
// single-vehicle (batch = 1) deploy case. A gtest parity suite compares this against
// fixtures generated by the Python pipeline (test/obs_fixture.txt).
//
// Standard library only (no Eigen / torch) to keep the on-car build lean.
#ifndef F1TENTH_RL_VEHICLE_RL_OBS_CORE_HPP_
#define F1TENTH_RL_VEHICLE_RL_OBS_CORE_HPP_

#include <array>
#include <string>
#include <vector>

namespace f1tenth_rl_vehicle
{

// Observation assembly parameters. Defaults match config.py DEFAULT_CONFIG["obs"]
// after the training/deploy parity alignment (scales 1.0, loose clip 50).
struct ObsConfig
{
  int num_obs = 384;
  int future_track_num_points = 60;
  double future_track_horizon_s = 6.0;
  // Lower bound on the future-point lookahead distance (matches training
  // obs_future_track_points: lookahead = max(speed * horizon, min_lookahead)).
  double future_track_min_lookahead_m = 5.0;
  double future_track_width = 2.2;  // deprecated: corridor uses per-vertex CSV widths
  double contact_margin_m = 0.08;
  double clip_obs = 50.0;
  double lin_vel_scale = 1.0;
  double ang_vel_scale = 1.0;
  double lin_acc_scale = 1.0;
  // 1v1: when enabled, a 6-dim opponent-relative block is appended at [384:390]
  // (num_obs becomes 390). Off by default to preserve the solo deploy.
  bool enable_opponent_obs = false;
  int opponent_obs_dim = 6;
  // Force [384:390] to zeros (1v0 sentinel) even when enable_opponent_obs is
  // true, so a 390-dim checkpoint can run without a working opponent detector.
  bool zero_opponent_obs = false;
};

// Opponent estimate in the map frame. Velocity is world-frame (the obs block
// rotates the relative velocity into the ego body frame). ``present`` is set by
// the detector; masking is applied by the caller (vehicle_obs_node).
struct OpponentState
{
  double pos_x = 0.0;
  double pos_y = 0.0;
  double vx = 0.0;  // world frame
  double vy = 0.0;  // world frame
  bool present = false;
};

// Current ego state in the track (map) frame. Velocities/accelerations are in the
// body frame, matching the training observation. tyre_slip is [slip_ratio x4,
// slip_angle x4]; deploy without per-wheel sensing passes zeros (gym parity).
// tyre_load is the per-wheel normal-load ratio Fz / Fz_static (order [LR, RR, LF,
// RF]); it defaults to the at-rest static ratio (1.0) when not estimated.
struct VehicleState
{
  double pos_x = 0.0;
  double pos_y = 0.0;
  double yaw = 0.0;
  double vx = 0.0;
  double vy = 0.0;
  double wz = 0.0;
  double ax = 0.0;
  double ay = 0.0;
  double last_throttle = 0.0;
  double last_steer = 0.0;
  std::array<double, 8> tyre_slip{};
  std::array<double, 4> tyre_load{{1.0, 1.0, 1.0, 1.0}};
};

// Result of projecting a point onto the (closed) centerline.
struct FrenetState
{
  int best_idx = 0;
  double best_t = 0.0;
  double s = 0.0;   // arc length along the closed loop
  double L = 0.0;   // total closed-loop length
  double proj_x = 0.0;
  double proj_y = 0.0;
  double dir_x = 1.0;
  double dir_y = 0.0;
};

// Lateral (Frenet) info at a map point: signed lateral offset from the centerline
// and the interpolated local half-widths. Used by the opponent obs block and the
// detector corridor gate.
struct LateralInfo
{
  double ey = 0.0;
  double w_left = 0.0;
  double w_right = 0.0;
  double s = 0.0;
  double L = 0.0;
};

struct TrackData
{
  std::vector<double> x;
  std::vector<double> y;
  std::vector<double> w_left;
  std::vector<double> w_right;
};

// Parse a centerline CSV with columns x_m, y_m, w_tr_right_m, w_tr_left_m. Mirrors
// track_io.load_track_csv. Throws std::runtime_error on missing columns / parse
// failure.
TrackData loadTrackCsv(const std::string & path);

// Per-wheel slip [slip_ratio x4, slip_angle x4]; port of f1tenth_env/car.py
// compute_tyre_slip. Wheel order [LR, RR, LF, RF]. Modern-PhysX denominators:
// slip_ratio = (wheel_speed - v_fwd) / (|v_fwd| + min_long), with min_long the
// active offset when the wheel has drive/brake torque applied (per-wheel `active`)
// else the larger passive (coasting) offset; slip_angle = atan(v_lat /
// (|v_fwd| + min_lat)). Offsets are scaled for the 1/10 car.
std::array<double, 8> computeTyreSlip(
  const std::array<double, 4> & v_fwd,
  const std::array<double, 4> & v_lat,
  const std::array<double, 4> & spin_rate,
  double wheel_radius,
  const std::array<bool, 4> & active,
  double min_lat = 0.2,
  double min_active_long = 0.1,
  double min_passive_long = 0.4);

// Per-wheel normal-load ratio Fz / Fz_static from body specific forces (m/s^2).
// Closed-form of f1tenth_sim/suspension.py quasi_static_loads divided by the static
// per-wheel load (mass cancels). +ax (forward) shifts load rearward; +ay (leftward)
// shifts load onto the right (outer) wheels. Wheel order [LR, RR, LF, RF]. Geometry
// defaults track f1tenth_sim VehicleParams. This is the on-car tyre-load estimate
// (ADR 0002 follow-up) used when no wheel-load sensing is available.
std::array<double, 4> computeQuasiStaticLoad(
  double ax,
  double ay,
  double h_cg = 0.05,
  double lf = 0.1584,
  double lr = 0.1666,
  double track_width = 0.253,
  double roll_stiffness_front = 0.47,
  double gravity = 9.81);

// On-car tyre-slip block estimator (8-dim [slip_ratio x4, slip_angle x4]).
struct SlipEstimatorConfig
{
  double wheel_radius_m = 0.053;
  double lf_m = 0.1584;
  double lr_m = 0.1666;
  double track_width_m = 0.253;
  double max_steer_rad = 0.33;
  double slip_min_lat = 0.2;
  double slip_min_active_long = 0.1;
  double slip_min_passive_long = 0.4;
  double vy_filter_tau_s = 0.5;
  double vx_ground_lp_alpha = 0.5;
  double slip_speed_min_mps = 0.3;
  std::array<double, 8> slip_obs_mean{};
};

struct SlipEstimatorInput
{
  double vesc_vx = 0.0;
  double dt = 0.1;
  double wz = 0.0;
  double last_steer = 0.0;
  double last_throttle = 0.0;
  bool have_imu = false;
  double imu_ay = 0.0;
  double imu_yaw_rate = 0.0;
  bool imu_use_for_yaw_rate = true;
  bool have_pf_vel = false;
  double pf_vx_body = 0.0;
  double pf_vy_body = 0.0;
};

struct SlipEstimatorState
{
  double vx_ground = 0.0;
  double vy_ground = 0.0;
};

std::array<double, 8> estimateSlipBlock(
  SlipEstimatorState & state,
  const SlipEstimatorConfig & cfg,
  const SlipEstimatorInput & in);

// First-order lag helpers (match F1tenthEnv steer_state / t_delta).
double lagAlpha(double control_dt, double t_delta);
double stepFirstOrderLag(double state, double target, double alpha);

// Map a policy action to (longitudinal_cmd, steering_angle_rad). Port of
// drive_math.map_action_to_force. longitudinal_cmd in [-1,1]: +drive, -brake.
std::pair<double, double> mapActionToForce(
  double throttle,
  double steering,
  double max_steer,
  double clip_actions = 1.0);

// Owns the track geometry and builds the 384-dim observation each control step.
class TrackObservationBuilder
{
public:
  TrackObservationBuilder(
    const std::vector<double> & xs,
    const std::vector<double> & ys,
    const std::vector<double> & w_left,
    const std::vector<double> & w_right,
    const ObsConfig & cfg,
    int coarse_stride = 10,
    int window = 40);

  // Assemble the observation. Returns a vector of length cfg.num_obs (float to
  // match the Float32MultiArray wire format). Throws if the assembled size differs.
  // When cfg.enable_opponent_obs is set, the 7-dim opponent block is appended from
  // `opp`; an absent opponent yields the exact zero sentinel.
  std::vector<float> build(
    const VehicleState & state, const OpponentState & opp = OpponentState{}) const;

  // Frenet projection of an arbitrary point (exposed for diagnostics / tests).
  FrenetState project(double px, double py) const;

  // Signed lateral offset + interpolated half-widths at a map point.
  LateralInfo lateral(double px, double py) const;

  int numCenterlinePoints() const { return n_; }

private:
  ObsConfig cfg_;
  int coarse_stride_;
  int window_;

  // Closed-loop cache (used by Frenet projection): segment starts C, segment
  // vectors, segment lengths, cumulative arc length, total length L, count M.
  std::vector<double> cx_, cy_;
  std::vector<double> seg_x_, seg_y_, seg_len_, cumlen_;
  double total_len_ = 0.0;
  int m_ = 0;
  std::vector<int> coarse_idx_;

  // Track widths (length of the original centerline).
  std::vector<double> wl_, wr_;
  int nw_ = 0;

  // Open-polyline cache (used by the future-track points): original centerline,
  // its segment lengths and cumulative arc length.
  std::vector<double> ox_, oy_;
  std::vector<double> oseg_len_, ocumlen_;
  int n_ = 0;
};

// --- LiDAR opponent detection (ROS-free, unit-testable) ----------------------

// Tuning for the LiDAR opponent detector. Distances in metres.
struct DetectorConfig
{
  // Adjacent beam endpoints within this distance join the same cluster.
  double cluster_gap_m = 0.30;
  // Keep clusters whose endpoint-to-endpoint extent is within this band (an
  // F1TENTH car footprint, projected at the observed range).
  double min_opponent_size_m = 0.05;
  // Tightened toward F1TENTH car length (~0.50 m); rejects oversized wall blobs.
  double max_opponent_size_m = 0.80;
  // Corridor gate: reject clusters whose centroid is closer to a track boundary
  // than this margin (i.e. wall returns). |ey| < half_width - margin to survive.
  double boundary_margin_m = 0.20;
  // Foreground gate: a real car stands in front of its angular background, so the
  // beams immediately flanking the cluster are either empty (free space) or at
  // least this much farther from the ego than the cluster's near edge. A contiguous
  // wall has a flanking return at a similar range and is rejected. <= 0 disables.
  double foreground_jump_m = 0.30;
  // Drop clusters whose near edge is farther than this from the ego (a single
  // LiDAR cannot reliably localise a distant car). <= 0 disables.
  double max_range_m = 10.0;
  // Reject clusters with fewer than this many valid beams (speckle / wall
  // fragments). <= 0 disables.
  int min_cluster_beams = 2;
  // Reject clusters whose near edge (closest beam to ego) is closer than this.
  // Bumper-range phantoms on solo laps are typically ~0.3 m. <= 0 disables.
  double min_ego_dist_m = 0.50;
  // Optional lower bound on cluster endpoint extent, separate from
  // min_opponent_size_m so the size band stays configurable. <= 0 disables.
  double min_extent_m = 0.0;
  // Require the cluster to span at least this many degrees in bearing
  // ((i1 - i0 + 1) * scan_angle_increment). Real cars subtend car_width/range
  // at the observed distance; set from typical range or leave 0 to disable.
  // <= 0 disables.
  double min_visible_angle_deg = 0.0;
  // LiDAR bearing increment (rad) for the angular-span gate. The ROS node passes
  // scan.angle_increment on each update(); tests may set it in config instead.
  double scan_angle_increment = 0.0;
  // Frame-to-frame association radius (centroid nearest neighbour).
  double max_assoc_dist_m = 1.50;
  // EMA factor on the estimated world-frame velocity (1.0 = no smoothing).
  double vel_alpha = 0.50;
  // A track must persist this many frames before it is reported present. This is
  // the primary confirmation gate and works for stationary opponents.
  int min_track_age_frames = 3;
  // If > 0, a track moving at least this fast confirms immediately (fast-track).
  // Never used to reject a slow / stationary track.
  double min_speed_mps = 0.0;
};

// One LiDAR beam already transformed into the map frame. invalid beams (out of
// range / non-finite) break cluster continuity.
struct ScanPoint
{
  double x = 0.0;
  double y = 0.0;
  bool valid = false;
};

// Output of a detector update: the confirmed opponent estimate (map frame).
struct DetectionResult
{
  bool present = false;
  double pos_x = 0.0;
  double pos_y = 0.0;
  double vx = 0.0;  // world frame
  double vy = 0.0;  // world frame
};

// A clustered candidate (exposed for tests).
struct Cluster
{
  double cx = 0.0;
  double cy = 0.0;
  double extent = 0.0;
  int count = 0;
  int i0 = 0;  // first beam index (for the foreground gate)
  int i1 = 0;  // last beam index
};

// Stateful single-opponent tracker. Clusters map-frame beams, gates them to the
// drivable corridor, associates the best candidate across frames, and estimates a
// smoothed world-frame velocity. Confirmation is persistence-based so a stationary
// opponent is still reported (velocity ~ 0).
class OpponentDetector
{
public:
  OpponentDetector(const TrackObservationBuilder & track, const DetectorConfig & cfg);

  // Process one scan (beams in beam order, map frame). ego_{x,y} is the ego map
  // position (used to pick the nearest candidate when initialising a track).
  // scan_angle_increment (rad): when > 0, overrides cfg_.scan_angle_increment for
  // the angular-span gate on this frame.
  DetectionResult update(
    const std::vector<ScanPoint> & beams, double ego_x, double ego_y, double stamp,
    double scan_angle_increment = 0.0);

  // Cluster beams by adjacent-endpoint gap. Exposed for tests.
  std::vector<Cluster> cluster(const std::vector<ScanPoint> & beams) const;

  // Corridor + size gate on a candidate cluster. Exposed for tests.
  bool inCorridor(const Cluster & c) const;

  // Foreground / stand-out gate: true when the cluster sits in front of its
  // angular background on both flanks (a real object, not a contiguous wall).
  // Exposed for tests. ego_{x,y} is the LiDAR origin in the map frame.
  bool standsOut(
    const std::vector<ScanPoint> & beams, const Cluster & c,
    double ego_x, double ego_y) const;

  // Beam-count and angular-span gates (min_cluster_beams, min_visible_angle_deg).
  // Exposed for tests.
  bool passesBeamGates(const Cluster & c, double scan_angle_increment) const;

  // Near-edge range from ego to the closest beam in the cluster. Exposed for tests.
  double clusterNearEdgeDist(
    const std::vector<ScanPoint> & beams, const Cluster & c,
    double ego_x, double ego_y) const;

private:
  const TrackObservationBuilder & track_;
  DetectorConfig cfg_;

  bool has_track_ = false;
  int age_ = 0;
  double tx_ = 0.0, ty_ = 0.0;
  double tvx_ = 0.0, tvy_ = 0.0;
  double t_stamp_ = 0.0;
};

}  // namespace f1tenth_rl_vehicle

#endif  // F1TENTH_RL_VEHICLE_RL_OBS_CORE_HPP_
